/*@@SAFELAB_LIB@@*/

// ---- Shared helpers (same block in every SafeLab workflow) ----
const rowsOf = (node) => $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const now = $now.setZone('Asia/Ho_Chi_Minh');
const today = now.toFormat('yyyy-MM-dd');
const nowIso = now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"); // e.g. 2026-10-11T21:30:00+07:00
const year = now.year;
const esc = SafeLab.escapeHtml;
const text = (v) => (v === null || v === undefined ? '' : String(v).trim());
const lower = (v) => text(v).toLowerCase();
// Google Sheets treats text starting with = + - @ as a formula: prefix ' so it is stored as plain text.
const sheetRow = (row) => Object.fromEntries(Object.entries(row).map(([k, v]) =>
  [k, typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v]));
const audit = (actor, action, entity, entityId, details) =>
  sheetRow({ ts: nowIso, actor: actor || 'system', action, entity, entity_id: entityId, details: text(details).slice(0, 1000) });
const link = (url, label) =>
  (text(url) ? `<a href="${esc(url)}">${esc(label)}</a>` : `${esc(label)} (link not configured in CONFIG)`);
const mail = (to, subject, body) => ({
  to: [...new Set([].concat(to).map(lower).filter(Boolean))].join(', '),
  subject: text(subject).replace(/\s+/g, ' '),
  html: `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5;color:#111">${body}` +
    '<p style="color:#6b7280;font-size:12px;margin-top:24px">Automated message from SafeLab (lab-safety approval system).</p></div>',
});
const cfg = SafeLab.configMap(rowsOf('Read CONFIG'));

// ---- 07 POST: record a REVIEW or PI decision ----
const secret = $env.SAFELAB_SECRET;
const baseUrl = text($env.SAFELAB_PUBLIC_URL || 'http://localhost:5678').replace(/\/+$/, '');
const result = (code, title, body, writes) => [{ json: { code, html:
  '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width,initial-scale=1">' +
  `<title>${esc(title)} – SafeLab</title><style>` +
  'body{font-family:Arial,sans-serif;font-size:15px;line-height:1.5;color:#111;background:#f9fafb;margin:0}' +
  'main{max-width:860px;margin:0 auto;padding:16px}h1{font-size:22px}table{max-width:100%}</style></head>' +
  `<body><main><h1>${esc(title)}</h1>${body}</main></body></html>`,
  experiments: [], approvals: [], audit: [], emails: [], ...(writes || {}) } }];

const b = $('POST decision').first().json.body || {};
const expId = text(b.exp);
const stage = text(b.stage).toUpperCase();
const token = text(b.token);
const decision = text(b.decision).toUpperCase();
const comment = text(b.comment);
const pageUrl = `safelab-decision?exp=${encodeURIComponent(expId)}&stage=${encodeURIComponent(stage)}&token=${encodeURIComponent(token)}`;
const DECISIONS = {
  APPROVE: 'Approve',
  APPROVE_WITH_CONDITIONS: 'Approve with conditions',
  CHANGES_REQUIRED: 'Changes required',
  REJECT: 'Reject',
};
const OUTCOME = {
  APPROVED: 'Approved',
  APPROVED_WITH_CONDITIONS: 'Approved with conditions',
  CHANGES_REQUIRED: 'Changes required – submit a new F04',
  REJECTED: 'Rejected',
};

if (!SafeLab.verifyToken(secret, expId, stage, token)) {
  return result(403, 'Invalid link', '<p>This approval link is not valid. Please use the link from the latest SafeLab email.</p>');
}
const exp = rowsOf('Read EXPERIMENTS').find((r) => text(r.exp_id).toUpperCase() === expId.toUpperCase());
if (!exp) return result(404, 'Experiment not found', `<p>${esc(expId)} does not exist in the EXPERIMENTS sheet.</p>`);
if (!DECISIONS[decision]) {
  return result(400, 'Choose a decision', `<p>Please <a href="${esc(pageUrl)}">go back</a> and choose a decision.</p>`);
}
if ((decision === 'APPROVE_WITH_CONDITIONS' || decision === 'CHANGES_REQUIRED') && !comment) {
  return result(400, 'Comment required',
    `<p>“${esc(DECISIONS[decision])}” needs a comment describing the conditions or required changes. ` +
    `Please <a href="${esc(pageUrl)}">go back</a> and add it.</p>`);
}
const next = SafeLab.nextState(exp, stage, decision);
if (!next.ok) {
  return result(409, 'Decision not recorded',
    `<p>${esc(next.error)}. ${esc(exp.exp_id)} is currently <b>${esc(exp.status)}</b> – it may already have been decided.</p>`);
}

// ---- valid decision ----
const id = text(exp.exp_id);
const reviewerEmail = lower(exp.reviewer_email);
const actor = stage === 'PI' ? lower(cfg.PI_EMAIL) : reviewerEmail;
const approvalId = SafeLab.nextId('APR', year, rowsOf('Read APPROVALS').map((r) => r.approval_id));
const updated = { ...exp, status: next.status, current_stage: next.current_stage, updated_at: nowIso };
const isHigh = text(exp.inherent_level).toUpperCase() === 'HIGH';
const permitNote = isHigh
  ? '<p style="color:#b91c1c"><b>Reminder (HIGH risk):</b> PI approval is the final INTERNAL approval only. ' +
    'External permits and institutional EHS approvals required by law must still be obtained before work starts.</p>'
  : '';
const emails = [];

if (next.status === 'PENDING_PI') {
  const piToken = SafeLab.makeToken(secret, id, 'PI');
  const url = `${baseUrl}/webhook/safelab-decision?exp=${encodeURIComponent(id)}&stage=PI&token=${encodeURIComponent(piToken)}`;
  emails.push(mail(cfg.PI_EMAIL, `[SafeLab] FINAL APPROVAL – ${id} ${text(exp.title)}`,
    '<h2>SAFELAB – FINAL APPROVAL</h2>' +
    `<p>Dear ${esc(cfg.PI_NAME || 'PI')}, experiment <b>${esc(id)}</b> passed safety review and needs your final approval.</p>` +
    `<p>Reviewer decision: <b>${esc(DECISIONS[decision])}</b> by ${esc(reviewerEmail)}` +
    (comment ? `<br>Reviewer comment: ${esc(comment).replace(/\r?\n/g, '<br>')}` : '') + '</p>' +
    `<p><a href="${esc(url)}" style="display:inline-block;padding:10px 18px;background:#1d4ed8;color:#fff;` +
    'text-decoration:none;border-radius:6px;font-weight:bold">Open final approval page</a></p>' +
    '<p style="color:#6b7280;font-size:12px">Opening the page does not change anything; the decision is only recorded when you submit the form.</p>' +
    permitNote +
    SafeLab.experimentSummaryHtml(updated, null, null,
      { exp_id: id, reviewer_decision: DECISIONS[decision], reviewer_comment: comment || '-' })));
} else {
  emails.push(mail([exp.leader_email, exp.submitted_by, reviewerEmail],
    `[SafeLab] ${OUTCOME[next.status] || next.status} – ${id} ${text(exp.title)}`,
    `<h2>${esc(id)}: ${esc(OUTCOME[next.status] || next.status)}</h2>` +
    `<p>Decision by the ${stage === 'PI' ? esc(cfg.PI_NAME || 'PI') + ' (final approval)' : 'safety reviewer'}: ` +
    `<b>${esc(DECISIONS[decision])}</b>` +
    (comment ? `<br>Comment / conditions: ${esc(comment).replace(/\r?\n/g, '<br>')}` : '') + '</p>' +
    (next.status === 'CHANGES_REQUIRED' || next.status === 'REJECTED'
      ? `<p>To continue, address the comments and submit a new ${link(cfg.FORM_F04_URL, 'F04 form')}.</p>` : '') +
    permitNote +
    SafeLab.experimentSummaryHtml(updated, null, null, { exp_id: id })));
}

const nextStep = next.status === 'PENDING_PI'
  ? `It has been sent to ${esc(cfg.PI_NAME || 'the PI')} for final approval.`
  : 'The experiment leader and reviewer have been notified by email.';
return result(200, 'Decision recorded',
  `<p><b>${esc(id)}</b> – ${esc(DECISIONS[decision])}. New status: <b>${esc(next.status)}</b>.</p><p>${nextStep}</p>` + permitNote,
  {
    experiments: [{ exp_id: id, status: next.status, current_stage: next.current_stage, updated_at: nowIso }],
    approvals: [sheetRow({
      approval_id: approvalId, exp_id: id, stage, reviewer_email: actor,
      decision, comment, decided_at: nowIso,
    })],
    audit: [audit(actor, `${stage}_DECISION`, 'EXPERIMENTS', id,
      `${decision} -> ${next.status}${comment ? ': ' + comment : ''}`)],
    emails: emails.filter((e) => e.to),
  });

/*@@SAFELAB_LIB@@*/

// ---- Shared helpers (same block in every SafeLab workflow) ----
const rowsOf = (node) => $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const now = $now.setZone('Asia/Ho_Chi_Minh');
const today = now.toFormat('yyyy-MM-dd');
const nowIso = now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"); // e.g. 2026-10-11T21:30:00+07:00
const year = now.year;
const esc = SafeLab.escapeHtml;
const text = (v) => (v === null || v === undefined ? '' : String(v).trim());
const lower = (v) => text(v).toLowerCase();
// Google Sheets treats text starting with = + - @ as a formula: prefix ' so it is stored as plain text.
const sheetRow = (row) => Object.fromEntries(Object.entries(row).map(([k, v]) =>
  [k, typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v]));
const audit = (actor, action, entity, entityId, details) =>
  sheetRow({ ts: nowIso, actor: actor || 'system', action, entity, entity_id: entityId, details: text(details).slice(0, 1000) });
const link = (url, label) =>
  (text(url) ? `<a href="${esc(url)}">${esc(label)}</a>` : `${esc(label)} (link not configured in CONFIG)`);
const mail = (to, subject, body) => ({
  to: [...new Set([].concat(to).map(lower).filter(Boolean))].join(', '),
  subject: text(subject).replace(/\s+/g, ' '),
  html: `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5;color:#111">${body}` +
    '<p style="color:#6b7280;font-size:12px;margin-top:24px">Automated message from SafeLab (lab-safety approval system).</p></div>',
});
const cfg = SafeLab.configMap(rowsOf('Read CONFIG'));

// ---- 07 GET: show the decision page. NEVER changes state (mail scanners prefetch links). ----
const page = (code, title, body) => [{ json: { code, html:
  '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width,initial-scale=1">' +
  `<title>${esc(title)} – SafeLab</title><style>` +
  'body{font-family:Arial,sans-serif;font-size:15px;line-height:1.5;color:#111;background:#f9fafb;margin:0}' +
  'main{max-width:860px;margin:0 auto;padding:16px}h1{font-size:22px}table{max-width:100%}' +
  'fieldset{border:1px solid #d1d5db;border-radius:6px;margin:16px 0}label{display:block;margin:6px 0}' +
  'textarea{width:100%;box-sizing:border-box;font:inherit}' +
  'button{padding:10px 18px;background:#1d4ed8;color:#fff;border:0;border-radius:6px;font-size:15px;cursor:pointer}' +
  '</style></head><body><main>' + `<h1>${esc(title)}</h1>${body}</main></body></html>` } }];

const q = $('GET decision page').first().json.query || {};
const expId = text(q.exp);
const stage = text(q.stage).toUpperCase();
const token = text(q.token);

if (!SafeLab.verifyToken($env.SAFELAB_SECRET, expId, stage, token)) {
  return page(403, 'Invalid link', '<p>This approval link is not valid. Please use the link from the latest SafeLab email.</p>');
}
const exp = rowsOf('Read EXPERIMENTS').find((r) => text(r.exp_id).toUpperCase() === expId.toUpperCase());
if (!exp) return page(404, 'Experiment not found', `<p>${esc(expId)} does not exist in the EXPERIMENTS sheet.</p>`);

const history = rowsOf('Read APPROVALS').filter((a) => text(a.exp_id).toUpperCase() === expId.toUpperCase());
const extra = { exp_id: exp.exp_id };
history.forEach((a) => {
  extra[`${text(a.stage).toLowerCase()}_decision`] = `${text(a.decision)} by ${text(a.reviewer_email)} (${text(a.decided_at)})`;
  if (text(a.comment)) extra[`${text(a.stage).toLowerCase()}_comment`] = text(a.comment);
});
const summary = SafeLab.experimentSummaryHtml(exp, null, null, extra);

if (!SafeLab.nextState(exp, stage, 'APPROVE').ok) {
  return page(409, `No decision needed – ${exp.exp_id}`,
    `<p>This experiment is currently <b>${esc(exp.status)}</b>, so no ${esc(stage)} decision can be recorded with this link.</p>` + summary);
}

const stageName = stage === 'PI' ? `Final approval – ${cfg.PI_NAME || 'PI'}` : 'Safety review';
const options = [
  ['APPROVE', 'Approve'],
  ['APPROVE_WITH_CONDITIONS', 'Approve with conditions (write the conditions below)'],
  ['CHANGES_REQUIRED', 'Changes required (explain below)'],
  ['REJECT', 'Reject'],
].map(([v, label]) => `<label><input type="radio" name="decision" value="${v}" required> ${esc(label)}</label>`).join('');
const form =
  // relative action -> POST /webhook/safelab-decision (same path as this page)
  '<form method="POST" action="safelab-decision">' +
  `<input type="hidden" name="exp" value="${esc(expId)}">` +
  `<input type="hidden" name="stage" value="${esc(stage)}">` +
  `<input type="hidden" name="token" value="${esc(token)}">` +
  `<fieldset><legend><b>Your decision</b></legend>${options}</fieldset>` +
  '<label><b>Comment / conditions</b> (required for conditions or changes)<br>' +
  '<textarea name="comment" rows="5"></textarea></label>' +
  '<p><button type="submit">Submit decision</button></p></form>';

const reminder = text(exp.inherent_level).toUpperCase() === 'HIGH'
  ? '<p style="color:#b91c1c"><b>HIGH risk:</b> PI approval is the final INTERNAL approval only; external permits / EHS approvals required by law are still needed.</p>'
  : '';
return page(200, `${stageName}: ${exp.exp_id}`, reminder + summary + form);
